input.sparql:
SELECT ?point ?cls ?ts WHERE {
  ?z rdfs:label "Perimeter_top_ZN_3" .
  ?z ?p ?point .
  FILTER(?p = brick:hasSubentity || ?p = brick:hasPoint)
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

SELECT ?ts WHERE { 
  ?z rdfs:label "Perimeter_top_ZN_3" .
  ?z brick:hasSubentity ?point .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
}

SELECT ?point WHERE { 
  ?z rdfs:label "Perimeter_top_ZN_3" .
  ?z brick:hasSubentity ?point .
  FILTER(str(?point) CONTAINS "Occupancy")
}

SELECT ?s WHERE {
  ?s a brick:OccupancySensor .
  ?s ref:hasTimeseriesId ?ts .
  FILTER(str(?s) CONTAINS "Zone_F4_Z02")
}

